; Generated by .claude/substitute_bar_build.py (a bare run writes it, --check compares): do not edit by hand.
; The SUBSTITUTE doll's HP tube beside each battle HUD (engine/battle/substitute_bar.asm).
; Fill pixels f = clamp(dollHP * capacity / dollMax, 1, capacity), dollMax = max(1, maxHP >> 2).
; Player: cells (19,9) (19,10) (19,11) under the mark (19,8); enemy: cells (0,2) (0,3) under the mark (0,1).

DEF SUBBAR_PLAYER_CAP EQU 19
DEF SUBBAR_ENEMY_CAP  EQU 11

; The two marks above the tubes are painted by hand (gfx/battle/substitute_mark.png: the player's, then the
; enemy's). They follow each system's generated set, in the ROM and in VRAM: its last two ids.
DEF NUM_SUBBAR_MARK_TILES EQU 2

; GBC: VRAM bank 1 from id $00 (gfx/battle/substitute_bar_gbc.png, then the marks), shown in cells whose
; attribute has bit 3.
DEF NUM_SUBBAR_GBC_TILES EQU 37
DEF SUBBAR_GBC_LINE_E EQU $21
DEF SUBBAR_GBC_SPILL  EQU $22
DEF SUBBAR_GBC_MARK_P EQU $23
DEF SUBBAR_GBC_MARK_E EQU $24

; DMG / SGB: bank 0, over font cells the GBC gives to its coloured status letters (blank on these systems)
; plus $d2 (gfx/battle/substitute_bar_dmg.png, then the marks, in three runs).
DEF NUM_SUBBAR_DMG_TILES EQU 17
DEF SUBBAR_DMG_RUN1     EQU $ca
DEF SUBBAR_DMG_RUN1_LEN EQU 6
DEF SUBBAR_DMG_RUN2     EQU $d2
DEF SUBBAR_DMG_RUN2_LEN EQU 1
DEF SUBBAR_DMG_RUN3     EQU $d5
DEF SUBBAR_DMG_RUN3_LEN EQU 10
DEF SUBBAR_DMG_LINE_E EQU $db
DEF SUBBAR_DMG_SPILL  EQU $dc
DEF SUBBAR_DMG_MARK_P EQU $dd
DEF SUBBAR_DMG_MARK_E EQU $de

SubstituteBarPlayerGBC:
; f = 1..19: top, middle, bottom
	db $0d, $04, $00 ; 1
	db $0d, $04, $01 ; 2
	db $0d, $04, $02 ; 3
	db $0d, $04, $03 ; 4
	db $0d, $05, $03 ; 5
	db $0d, $06, $03 ; 6
	db $0d, $07, $03 ; 7
	db $0d, $08, $03 ; 8
	db $0d, $09, $03 ; 9
	db $0d, $0a, $03 ; 10
	db $0d, $0b, $03 ; 11
	db $0d, $0c, $03 ; 12
	db $0e, $0c, $03 ; 13
	db $0f, $0c, $03 ; 14
	db $10, $0c, $03 ; 15
	db $11, $0c, $03 ; 16
	db $12, $0c, $03 ; 17
	db $13, $0c, $03 ; 18
	db $14, $0c, $03 ; 19

SubstituteBarEnemyGBC:
; f = 1..11: top, bottom
	db $19, $15 ; 1
	db $19, $16 ; 2
	db $19, $17 ; 3
	db $19, $18 ; 4
	db $1a, $18 ; 5
	db $1b, $18 ; 6
	db $1c, $18 ; 7
	db $1d, $18 ; 8
	db $1e, $18 ; 9
	db $1f, $18 ; 10
	db $20, $18 ; 11

SubstituteBarPlayerDMG:
; f = 1..19: top, middle, bottom
	db $cf, $cc, $ca ; 1
	db $cf, $cc, $ca ; 2
	db $cf, $cc, $ca ; 3
	db $cf, $cc, $cb ; 4
	db $cf, $cc, $cb ; 5
	db $cf, $cc, $cb ; 6
	db $cf, $cc, $cb ; 7
	db $cf, $cd, $cb ; 8
	db $cf, $cd, $cb ; 9
	db $cf, $cd, $cb ; 10
	db $cf, $cd, $cb ; 11
	db $cf, $ce, $cb ; 12
	db $cf, $ce, $cb ; 13
	db $cf, $ce, $cb ; 14
	db $cf, $ce, $cb ; 15
	db $d2, $ce, $cb ; 16
	db $d2, $ce, $cb ; 17
	db $d2, $ce, $cb ; 18
	db $d5, $ce, $cb ; 19

SubstituteBarEnemyDMG:
; f = 1..11: top, bottom
	db $d8, $d6 ; 1
	db $d8, $d6 ; 2
	db $d8, $d6 ; 3
	db $d8, $d7 ; 4
	db $d8, $d7 ; 5
	db $d8, $d7 ; 6
	db $d8, $d7 ; 7
	db $d9, $d7 ; 8
	db $d9, $d7 ; 9
	db $d9, $d7 ; 10
	db $da, $d7 ; 11

	ASSERT NUM_SUBBAR_DMG_TILES == SUBBAR_DMG_RUN1_LEN + SUBBAR_DMG_RUN2_LEN + SUBBAR_DMG_RUN3_LEN
